# Three narrow Gaussian peaks, sampled finely enough to remain smooth at any size.
def gaussian_logo_path():
    points = []
    for i in range(153):
        x = 3 + i / 4
        y = 35 - 12 * math.exp(-0.5 * ((x - 11) / 0.9) ** 2) - 21 * math.exp(-0.5 * ((x - 22) / 0.95) ** 2) - 29 * math.exp(-0.5 * ((x - 33) / 1.05) ** 2)
        points.append(f'{"M" if i == 0 else "L"}{x:.2f} {y:.3f}')
    return ' '.join(points)

peak_path = gaussian_logo_path()
logo=f'<svg viewBox="0 0 44 44" aria-hidden="true"><path d="{peak_path}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round"/><path d="M3 40h38" stroke="currentColor" opacity=".4"/></svg>'
