def page(slug,title,desc,body,extra=''):
    nav=''.join(f'<a href="/{"" if k=="index" else k+".html"}" '+('aria-current="page"' if k==slug else '')+f'>{v}</a>' for k,v in NAV)
    text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — GC Simulator</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta name="theme-color" content="#3b1900"><link rel="canonical" href="https://gcsimulator.org/{'' if slug=='index' else slug}"><link rel="stylesheet" href="/assets/site.css"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml">{extra}<script src="/assets/site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap masthead"><a class="brand" href="/">{logo}<span><strong>GC Simulator</strong><small>the free, open-source GC simulator</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="site-nav">Menu</button></div><div class="nav-band"><nav id="site-nav" class="wrap nav" aria-label="Main navigation">{nav}</nav></div></header><main id="main" class="wrap">{body}</main><footer class="footer"><div class="wrap"><div class="footer-top"><div><a class="footer-brand" href="/">GC Simulator</a></div><div class="footer-links"><a href="/about.html">About the project</a><a href="/development.html">Source code</a><a href="https://hplcsimulator.org">HPLC Simulator ↗</a></div></div><div class="footer-bottom"><span>GC Simulator by Paul Boswell</span><a href="https://creativecommons.org/licenses/by-nc-sa/3.0/us/">CC BY-NC-SA 3.0 US</a></div></div></footer></body></html>'''
    import re
    def version_asset(m):
        path=m[1];file=PUBLIC/path.lstrip('/')
        return '"'+path+'?v='+hashlib.sha256(file.read_bytes()).hexdigest()[:10]+'"' if file.exists() else m[0]
    text=re.sub(r'"(/assets/[^"?]+\.(?:css|js|svg))"',version_asset,text)
    (PUBLIC/f'{slug}.html').write_text(text,encoding='utf-8')
def heading(k,title,p):return f'<div class="page-heading"><h1>{title}</h1><p>{p}</p></div>'
def panel(title,p):return '<article class="panel">'+(f'<h2>{title}</h2>' if title else '')+p+'</article>'

