with zipfile.ZipFile(PUBLIC/'downloads/gc-simulator-java-source.zip','w',zipfile.ZIP_DEFLATED) as z:
    src=ROOT/'legacy-source/src'
    for p in src.rglob('*'):
        if p.is_file():z.write(p,str(Path('src')/p.relative_to(src)))
with zipfile.ZipFile(PUBLIC/'downloads/gc-simulator-web.zip','w',zipfile.ZIP_DEFLATED) as z:
    for folder in ['public','simulator','scripts','tests','functions','legacy-source']:
        for p in (ROOT/folder).rglob('*'):
            if p.is_file() and p.suffix not in ['.zip','.class'] and 'java' not in p.relative_to(ROOT).parts:z.write(p,str(p.relative_to(ROOT)))
    for name in ['build_site.py','package.json','worker.js','wrangler.jsonc','README.md','HPLC-PARITY.md']:
        if (ROOT/name).exists():z.write(ROOT/name,name)
